<?php $statusLabels=['open'=>'Offen','waiting_admin'=>'Wartet auf Admin','waiting_seller'=>'Wartet auf Verkäuferin','closed'=>'Geschlossen'];?>
<main class="section">
<div class="admin-page-intro"><div><span class="eyebrow">Kommunikation</span><h1>Support</h1><p>Öffentliche Kontaktanfragen und Verkäuferinnen-Tickets zentral bearbeiten.</p></div></div>
<form method="get" class="card filters"><input type="search" name="q" value="<?=App\Core\View::e($filterTerm)?>" placeholder="Ticket, Name, E-Mail oder Betreff"><select name="status"><option value="">Alle Status</option><?php foreach($statusLabels as $k=>$v):?><option value="<?=$k?>" <?=$filterStatus===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select><button class="btn primary">Filtern</button><a class="btn ghost" href="/admin/support">Zurücksetzen</a></form>
<div class="worklist"><?php foreach($tickets as $t):?><a class="work-row" href="/admin/support/<?=$t['id']?>"><div><b><?=App\Core\View::e($t['ticket_number'])?> · <?=App\Core\View::e($t['subject'])?></b><span><?=App\Core\View::e($t['name'])?> · <?=App\Core\View::e($t['email'])?> · <?=date('d.m.Y H:i',strtotime($t['updated_at']))?></span></div><span class="seller-status <?=$t['status']==='waiting_admin'||$t['status']==='open'?'warn':($t['status']==='closed'?'':'ok')?>"><?=App\Core\View::e($statusLabels[$t['status']]??$t['status'])?></span></a><?php endforeach;?><?php if(!$tickets):?><div class="empty">Keine Supporttickets gefunden.</div><?php endif;?></div>
</main>